package com.vit.archds.entity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="audit_logs",indexes=@Index(name="idx_audit_user",columnList="user_id")) public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @Column(nullable=false) private String action; @Column(length=200) private String resource; @Column(length=2000) private String metadata; @Column(nullable=false,updatable=false) private Instant timestamp=Instant.now(); public AuditLog(){} public AuditLog(User u,String a,String r,String m){user=u;action=a;resource=r;metadata=m;} public Long getId(){return id;} public String getAction(){return action;} public String getResource(){return resource;} public String getMetadata(){return metadata;} public Instant getTimestamp(){return timestamp;} }
